package com.supakeyboard.neuralkey.ime.typing

import java.io.InputStream
import java.util.zip.GZIPInputStream

/**
 * Read-only, frequency-ranked English language model bundled with the app
 * (generated by `tools/build_language_model.py`).
 *
 * @property scores word -> log-frequency score (ln(count) * 10, roughly 90..240)
 * @property cased word -> preferred capitalisation (London, I'm, OK, iPhone)
 * @property bigrams previous word -> most likely next words, best first
 */
class LanguageModel(
    val scores: Map<String, Int>,
    val cased: Map<String, String>,
    val bigrams: Map<String, List<String>>
) {
    companion object {
        const val UNIGRAM_ASSET = "english_lm.dict"
        const val BIGRAM_ASSET = "english_bigrams.dict"

        val EMPTY = LanguageModel(emptyMap(), emptyMap(), emptyMap())

        fun parse(unigramLines: Sequence<String>, bigramLines: Sequence<String>): LanguageModel {
            val scores = HashMap<String, Int>(1 shl 17)
            val cased = HashMap<String, String>()
            for (line in unigramLines) {
                val parts = line.split('\t')
                if (parts.size < 2 || parts[0].isEmpty()) continue
                val score = parts[1].toIntOrNull() ?: continue
                scores[parts[0]] = score
                if (parts.size >= 3 && parts[2].isNotEmpty()) cased[parts[0]] = parts[2]
            }
            val bigrams = HashMap<String, List<String>>(1 shl 15)
            for (line in bigramLines) {
                val tab = line.indexOf('\t')
                if (tab <= 0) continue
                bigrams[line.substring(0, tab)] = line.substring(tab + 1).split(' ').filter { it.isNotEmpty() }
            }
            return LanguageModel(scores, cased, bigrams)
        }

        /** Loads both gzip assets; [open] maps an asset name to its stream (e.g. `assets::open`). */
        fun load(open: (String) -> InputStream): LanguageModel =
            GZIPInputStream(open(UNIGRAM_ASSET)).bufferedReader().useLines { unigrams ->
                GZIPInputStream(open(BIGRAM_ASSET)).bufferedReader().useLines { bigrams ->
                    parse(unigrams, bigrams)
                }
            }
    }
}
